// VIOC_ai_transport.sqf - parche ai_transport de VIOC (2026-10-16). No es del autor de la mision.
// Lo carga init.sqf SOLO en el servidor. Parametros de lobby (sin lobby valen los de por defecto):
//   VIOC_AI_TRANSPORT          0 = no (todo como el original), 1 = si (por defecto), 2 = si, pero sin compras
//   VIOC_AI_TRANSPORT_MOUNT    subir si el objetivo esta a mas de X m (900 por defecto)
//   VIOC_AI_TRANSPORT_DISMOUNT bajar a X m del objetivo (500 por defecto; tambien la distancia a la que la FSM de la mision
//                              baja a los pasajeros, CTI_AI_TEAMS_CARGO_VEHICLES_DISEMBARK_RANGE, que era 850)
//
// Un solo bucle (cada VIOC_AT_PERIOD s) sobre los equipos IA de oeste y este (CTI_CO_FNC_GetSideGroups). Nunca toca grupos
// con algun jugador, el grupo del comandante, guarniciones de pueblo, operaciones especiales ni equipos aereos.
//  A) Equipo SIN vehiculos propios (infanteria): con el objetivo (cti_order_pos) lejos y sin enemigos conocidos a menos de
//     VIOC_AT_THREAT m, y al menos VIOC_AT_MIN_INF infantes:
//     1) toma un vehiculo VACIO de su bando a menos de VIOC_AT_TAKE_RANGE m (que se mueva, con combustible, poco danado, con
//        asientos; nunca civil, de jugadores o usado por ellos en 30 min, con un jugador a menos de 60 m, de la base, de apoyo,
//        el HQ, aparcado de airfields, VIOC_KEEP ni de operaciones especiales): uno (o dos) del equipo pasan a ser su tripulacion;
//     2) si no hay y el equipo es de rol infanteria (cti_role en CTI_SQUADS_<bando>_KIND_INFANTRY), compra UN transporte
//        (modo 1): la clase mas barata con asientos para el equipo (prefiere uno armado si cuesta menos del 30 % de sus fondos)
//        de las listas de la fabrica ligera y pesada de su bando, con su nivel de mejora, fondos, tope de IA de perf_cleanup
//        (tripulacion incluida) y politica de contemporary_assets, por la compra normal (CTI_SE_FNC_OnClientPurchase con
//        destino = el BANDO, como las compras que crean su propio grupo; paga el equipo), con la regla de compra de la FSM
//        (cerca de la fabrica o Control Center al alcance) y nace en el punto propio seguro mas cercano al equipo (la regla
//        de ai_front_spawn). La compra se sigue por su semilla (VIOC_AT_PEND) mientras este en la cola de la fabrica.
//     El transporte lleva su tripulacion en un GRUPO APARTE (variable vioc_at_owner = el equipo): asi update_ai.fsm no mete
//     al jefe de conductor ni borra al conductor. Estados: CREW (la tripulacion tomada sube), GO (va a buscar al jefe),
//     LOAD (para y suben: el jefe primero; sin jugadores a VIOC_AT_PLAYER_RANGE m suben al instante con moveIn*), RIDE (va
//     hasta VIOC_AT_DISMOUNT + 50 m del objetivo, mejor por carretera), DROP (para, se bajan y el equipo recarga su orden),
//     SUPPORT (si es armado sigue a la infanteria a 150-250 m; si no, se queda atras y se aparta de enemigos cercanos).
//     Baja antes si el vehiculo recibe un impacto, se dana o hay enemigos conocidos cerca. Vuelve a recoger con la
//     siguiente orden lejana. Si el equipo se queda sin infanteria 10 min, el jefe queda a mas de VIOC_AT_MAX_CHASE m 5 min,
//     pasa a tener vehiculos propios o lo toma un jugador, el transporte se suelta: la tripulacion tomada vuelve a su equipo; el comprado se borra (con su tripulacion)
//     cuando no hay jugadores a VIOC_AT_PLAYER_RANGE m.
//  B) Equipo CON vehiculos propios (motorizados, blindados o mixtos): la infanteria del equipo a pie (no el jefe, que la FSM
//     pone de conductor) llena primero las torretas vacias (artillero, comandante) y, con el objetivo lejos, los asientos de
//     pasajero (tambien los FFV); baja al llegar, con impacto o con enemigos cerca. Si a esos vehiculos les sobran 4 o mas
//     asientos y el equipo casi no tiene infanteria, compra 3-5 soldados en el cuartel (CTI_SE_FNC_AI_PurchaseSquad) para
//     llevarlos (modo 1, cada VIOC_AT_INF_COOLDOWN s como mucho).
// LAMBS Danger: en los vehiculos PROPIOS de un equipo (B) su cerebro de blindados baja a los pasajeros en combate (Eject +
// allowGetIn false); se detecta y al volver a subir se pone allowGetIn true. En los TRANSPORTES (A) la tripulacion lleva
// lambs_danger_disableAI = true (la variable de unidad de LAMBS: fnc_isForcedExit.sqf la saca de su FSM de peligro; LAMBS no
// tiene un interruptor solo para el cerebro de vehiculos), asi no expulsa al conductor ni lanza el blindado al asalto: las
// bajadas y los movimientos los decide este script. Ademas el transporte va con setUnloadInCombat [false, false]
// (canUnloadInCombat, que LAMBS mira antes de expulsar) y VIOC_KEEP = true (perf_cleanup no lo borra) mientras se usa.
//
// Consola (servidor; en partida alojada "Ejecucion local"):
//   hint (call VIOC_AT_fnc_info);            equipos IA, su infanteria, vehiculos, transporte y estado (copia al portapapeles)
//   VIOC_AT_DEBUG = true;                    mensajes de cada cambio de estado (systemChat del anfitrion y diag_log)
//   [call VIOC_AT_fnc_nearTeam, player getPos [2500, getDir player]] call VIOC_AT_fnc_testOrder;  manda lejos al equipo IA
//                                            mas cercano a ti (orden MOVE, la FSM la recoge en unos segundos)
//   (call VIOC_AT_fnc_nearTeam) setVariable ["vioc_at_buyT", -100000];   sin espera para su proxima compra
//   VIOC_AT_INFO = [compras, tomados, subidas, bajadas al llegar, bajadas en combate, compras de infanteria, soltados, borrados]

if (!isServer) exitWith {};

//--- Ajustes
VIOC_AT_PERIOD = 10;            // s entre pasadas del bucle
VIOC_AT_THREAT = 500;           // m: enemigo conocido a esta distancia = combate (no se sube; se baja)
VIOC_AT_PICKUP = 150;           // m: el transporte para a esta distancia del jefe para recoger
VIOC_AT_BOARD_RANGE = 250;      // m: suben los del equipo a esta distancia del vehiculo
VIOC_AT_INSTANT = 150;          // m: sin jugadores cerca, los que esten a esta distancia suben al instante
VIOC_AT_PLAYER_RANGE = 1500;    // m: "sin jugadores cerca"
VIOC_AT_TAKE_RANGE = 300;       // m: vehiculos vacios propios que un equipo puede tomar
VIOC_AT_MIN_INF = 4;            // infantes a pie para tomar o comprar un transporte
VIOC_AT_BUY_COOLDOWN = 600;     // s entre compras de transporte de un mismo equipo
VIOC_AT_INF_COOLDOWN = 600;     // s entre compras de infanteria para los vehiculos de un mismo equipo
VIOC_AT_MAX_SIDE = 6;           // transportes (con grupo aparte) a la vez por bando
VIOC_AT_MAX_DELIVERY = 2500;    // m: el transporte comprado tiene que nacer a menos de esto del jefe (< VIOC_AT_MAX_CHASE)
VIOC_AT_MAX_CHASE = 3500;       // m: no va a buscar a un jefe mas lejos que esto...
VIOC_AT_FAR_RELEASE = 300;      // s: ...y si el jefe sigue mas lejos este tiempo, se suelta el transporte
VIOC_AT_LOAD_TIME = 75;         // s de espera para subir
VIOC_AT_IDLE_RELEASE = 600;     // s con menos de 2 infantes en el equipo: se suelta el transporte
VIOC_AT_DEBUG = false;          // true: mensajes de cada cambio

//--- Estado (servidor)
VIOC_AT_MODE = 1;
VIOC_AT_MOUNT = 900;
VIOC_AT_DISMOUNT = 500;
VIOC_AT_MOUNT_EFF = 900;
VIOC_AT_LIST = [];              // [vehiculo, grupo de tripulacion, equipo, comprado, bando] (sigue a la tripulacion aunque el vehiculo desaparezca)
VIOC_AT_PEND = [];              // compras pedidas: [semilla, equipo, hora, fabrica, recibida, hora en que salio de la cola]
VIOC_AT_INFO = [0, 0, 0, 0, 0, 0, 0, 0];
VIOC_AT_CLASSES = createHashMap;

//=====================================================================================================================
// Utilidades
//=====================================================================================================================
VIOC_AT_fnc_log = {
	params ["_msg"];
	if (VIOC_AT_DEBUG) then {
		diag_log format ["[VIOC_AT] %1", _msg];
		if (hasInterface) then {systemChat format ["[AT] %1", _msg]};
	};
};

VIOC_AT_fnc_stat = {
	params ["_i"];
	VIOC_AT_INFO set [_i, (VIOC_AT_INFO select _i) + 1];
};

//--- [posicion, radio] -> true si no hay jugadores vivos a esa distancia
VIOC_AT_fnc_noPlayers = {
	params ["_pos", "_r"];
	(allPlayers findIf {alive _x && {(_x distance2D _pos) < _r}}) < 0
};

//--- [unidad, radio] -> true si su grupo conoce un enemigo a menos de radio
VIOC_AT_fnc_threat = {
	params ["_u", "_r"];
	if (isNull _u || {!alive _u}) exitWith {false};
	private _e = _u findNearestEnemy _u;
	!isNull _e && {(_e distance _u) < _r}
};

//--- [objeto o posicion, lista de unidades] -> la mas cercana (o objNull)
VIOC_AT_fnc_nearest = {
	params ["_c", "_list"];
	private _best = objNull;
	private _bd = 1e9;
	{
		private _d = _x distance2D _c;
		if (_d < _bd) then {_best = _x; _bd = _d};
	} forEach _list;
	_best
};

//--- [grupo] -> destino de su orden ([x, y, 0]) o []
VIOC_AT_fnc_dest = {
	params ["_g"];
	private _p = _g getVariable "cti_order_pos";
	if (isNil "_p") exitWith {[]};
	if (_p isEqualType objNull) exitWith {
		if (isNull _p) then {[]} else {private _q = getPosATL _p; [_q select 0, _q select 1, 0]}
	};
	if (_p isEqualType [] && {count _p >= 2} && {(_p select 0) isEqualType 0} && {(_p select 1) isEqualType 0}) exitWith {[_p select 0, _p select 1, 0]};
	[]
};

//--- [config de torreta] -> true si tiene un arma de verdad (no humo, bengalas, bocina ni designador)
VIOC_AT_fnc_hasWeapon = {
	params ["_t"];
	((getArray (_t >> "weapons")) findIf {
		private _w = toLower _x;
		((_w find "smoke") < 0) && {(_w find "flare") < 0} && {(_w find "horn") < 0} && {(_w find "designator") < 0} && {(_w find "fake") < 0}
	}) >= 0
};

//--- [clase] -> [asientos de pasajero (transportSoldier + FFV), tripulacion que crea la compra IA, armado] (con cache)
VIOC_AT_fnc_classInfo = {
	params ["_cls"];
	private _k = toLower _cls;
	private _hit = VIOC_AT_CLASSES get _k;
	if (!isNil "_hit") exitWith {_hit};
	private _cfg = configFile >> "CfgVehicles" >> _cls;
	private _seats = getNumber (_cfg >> "transportSoldier");
	private _armed = false;
	private _tur = _cfg >> "turrets";
	for "_i" from 0 to (count _tur) - 1 do {
		private _t = _tur select _i;
		if (isClass _t) then {
			if ("CargoTurret" in ([_t, true] call BIS_fnc_returnParents)) then {
				_seats = _seats + 1;
			} else {
				if ([_t] call VIOC_AT_fnc_hasWeapon) then {_armed = true};
				private _sub = _t >> "turrets";
				for "_j" from 0 to (count _sub) - 1 do {
					private _s = _sub select _j;
					if (isClass _s && {[_s] call VIOC_AT_fnc_hasWeapon}) then {_armed = true};
				};
			};
		};
	};
	private _res = [_seats, 1 + count (_cls call CTI_CO_FNC_GetVehicleTurrets), _armed];
	VIOC_AT_CLASSES set [_k, _res];
	_res
};

//--- [vehiculo] -> asientos de pasajero libres (de fullCrew: [unidad, rol, indice, torreta, FFV]); primero los de carga
VIOC_AT_fnc_freePass = {
	params ["_v"];
	private _all = (fullCrew [_v, "", true]) select {isNull (_x select 0)};
	(_all select {(toLower (_x select 1)) == "cargo"}) + (_all select {((toLower (_x select 1)) == "turret") && {_x select 4} && {!(_v lockedTurret (_x select 3))}})
};

//--- [vehiculo] -> torretas de tripulacion libres (artillero, comandante, torretas que no son FFV)
VIOC_AT_fnc_freeCrew = {
	params ["_v"];
	(fullCrew [_v, "", true]) select {
		isNull (_x select 0) && {((toLower (_x select 1)) in ["gunner", "commander"]) || {((toLower (_x select 1)) == "turret") && {!(_x select 4)}}} && {((_x select 3) isEqualTo []) || {!(_v lockedTurret (_x select 3))}} //--- VIOC crew_fix: nunca un puesto bloqueado (lockTurret de RHS/CUP, p. ej. estaciones alternativas del M1)
	}
};

//--- [unidad, vehiculo, asiento (entrada de fullCrew), al instante]: la sube (o le ordena subir) a ese asiento
VIOC_AT_fnc_seat = {
	params ["_u", "_v", "_e", "_instant"];
	private _role = toLower (_e select 1);
	[_u] allowGetIn true;
	switch (_role) do {
		case "driver": {_u assignAsDriver _v; if (_instant) then {_u moveInDriver _v}};
		case "gunner": {_u assignAsGunner _v; if (_instant) then {_u moveInGunner _v}};
		case "commander": {_u assignAsCommander _v; if (_instant) then {_u moveInCommander _v}};
		case "turret": {_u assignAsTurret [_v, _e select 3]; if (_instant) then {_u moveInTurret [_v, _e select 3]}};
		default {_u assignAsCargoIndex [_v, _e select 2]; if (_instant) then {_u moveInCargo [_v, _e select 2]}};
	};
	if !(_instant) then {[_u] orderGetIn true};
	_u setVariable ["vioc_at_ride", _v];
	_u setVariable ["vioc_at_rideT", time];
	_u setVariable ["vioc_at_outT", nil];
};

//--- [vehiculo, unidades]: se bajan (se quita la asignacion; si siguen dentro 25 s con el vehiculo quieto, moveOut)
VIOC_AT_fnc_unload = {
	params ["_v", "_units"];
	{
		unassignVehicle _x;
		_x setVariable ["vioc_at_ride", nil];
		_x setVariable ["vioc_at_crew", nil];
		if !(isNull objectParent _x) then {_x setVariable ["vioc_at_outT", time]};
	} forEach _units;
	_units orderGetIn false;
};

//--- [unidades]: los que siguen dentro mucho despues de la orden de bajar salen con moveOut (vehiculo quieto)
VIOC_AT_fnc_forceOut = {
	params ["_units"];
	{
		private _t = _x getVariable "vioc_at_outT";
		if (!isNil "_t") then {
			private _ov = objectParent _x;
			if (isNull _ov) then {_x setVariable ["vioc_at_outT", nil]} else {
				if ((time - _t) > 25 && {(speed _ov) < 3} && {local _ov}) then {moveOut _x; _x setVariable ["vioc_at_outT", nil]};
			};
		};
	} forEach _units;
};

//--- [unidades, grupo]: asignados que aun no subieron; pasado VIOC_AT_LOAD_TIME suben al instante (sin jugadores cerca) o se
//--- quedan a pie. Devuelve los que siguen pendientes.
VIOC_AT_fnc_pending = {
	params ["_foot", "_g"];
	private _left = [];
	{
		private _u = _x;
		private _rv = _u getVariable ["vioc_at_ride", objNull];
		if (!isNull _rv && {!isNil {_u getVariable "vioc_at_rideT"}}) then {
			if (!alive _rv || {!canMove _rv}) then {
				unassignVehicle _u; [_u] orderGetIn false; _u setVariable ["vioc_at_ride", nil]; _u setVariable ["vioc_at_crew", nil];
			} else {
				if ((time - (_u getVariable ["vioc_at_rideT", time])) > VIOC_AT_LOAD_TIME) then {
					private _done = false;
					if ((_u distance2D _rv) < 300 && {[getPosATL _rv, VIOC_AT_PLAYER_RANGE] call VIOC_AT_fnc_noPlayers}) then {
						private _r = assignedVehicleRole _u;
						private _kind = toLower (_r param [0, ""]);
						if (_kind == "driver" && {isNull driver _rv}) then {_u moveInDriver _rv};
						if (_kind == "turret" && {count _r > 1}) then {_u moveInTurret [_rv, _r select 1]};
						if (_kind == "cargo") then {_u moveInCargo _rv};
						_done = (objectParent _u) isEqualTo _rv;
					};
					if !(_done) then {
						unassignVehicle _u; [_u] orderGetIn false; _u setVariable ["vioc_at_ride", nil]; _u setVariable ["vioc_at_crew", nil];
						_g setVariable ["vioc_at_noMountT", time + 120];
					};
				} else {_left pushBack _u};
			};
		};
	} forEach _foot;
	_left
};

//--- [vehiculo]: abre el vehiculo a la IA (lock 2 -> 3 "cerrado para jugadores") y vigila los impactos
VIOC_AT_fnc_prepare = {
	params ["_v"];
	if (local _v && {(locked _v) >= 2}) then {
		if (isNil {_v getVariable "vioc_at_lock0"}) then {_v setVariable ["vioc_at_lock0", locked _v]};
		if ((locked _v) != 3) then {_v lock 3};
	};
	if (isNil {_v getVariable "vioc_at_eh"}) then {
		_v setVariable ["vioc_at_eh", _v addEventHandler ["hit", {(_this select 0) setVariable ["vioc_at_hitT", time]}]];
	};
};

//--- [grupo del transporte]: su tripulacion sale del FSM de peligro de LAMBS (variable de unidad lambs_danger_disableAI, que
//--- lambs_danger_fnc_isForcedExit mira); se marca para devolverla si vuelven a un equipo
VIOC_AT_fnc_crewPrep = {
	params ["_tg"];
	{
		if !(_x getVariable ["lambs_danger_disableAI", false]) then {
			_x setVariable ["lambs_danger_disableAI", true];
			_x setVariable ["vioc_at_lambsOff", true];
		};
	} forEach (units _tg);
};

VIOC_AT_fnc_crewRestore = {
	params ["_units"];
	{
		if (_x getVariable ["vioc_at_lambsOff", false]) then {_x setVariable ["lambs_danger_disableAI", nil]; _x setVariable ["vioc_at_lambsOff", nil]};
	} forEach _units;
};

//--- [grupo de transporte, vehiculo, posicion, forzar]: orden de movimiento al grupo (solo si cambia > 60 m)
VIOC_AT_fnc_goto = {
	params ["_tg", "_v", "_pos", ["_force", false]];
	if (count _pos < 2 || {surfaceIsWater _pos} || {isNull _tg}) exitWith {};
	private _p = [_pos select 0, _pos select 1, 0];
	private _last = _v getVariable ["vioc_at_goto", []];
	if (_force || {count _last < 2} || {(_last distance2D _p) > 60}) then {
		_tg move _p;
		_v setVariable ["vioc_at_goto", _p];
	};
};

//--- [vehiculo, estado]
VIOC_AT_fnc_setState = {
	params ["_v", "_st"];
	private _old = _v getVariable ["vioc_at_state", ""];
	_v setVariable ["vioc_at_state", _st];
	_v setVariable ["vioc_at_t", time];
	_v setVariable ["vioc_at_stuck", 0];
	[format ["%1 %2 (%3): %4 -> %5", side (_v getVariable ["vioc_at_tg", grpNull]), typeOf _v, groupId (_v getVariable ["vioc_at_owner", grpNull]), _old, _st]] call VIOC_AT_fnc_log;
};

//--- [vehiculo] -> pasadas seguidas casi sin moverse
VIOC_AT_fnc_stuck = {
	params ["_v"];
	private _lp = _v getVariable ["vioc_at_lp", [0, 0, 0]];
	private _n = _v getVariable ["vioc_at_stuck", 0];
	if ((_v distance2D _lp) < 25 && {(speed _v) < 3}) then {_n = _n + 1} else {_n = 0};
	_v setVariable ["vioc_at_lp", getPosATL _v];
	_v setVariable ["vioc_at_stuck", _n];
	_n
};

//--- [vehiculo, destino] -> punto para bajar: a VIOC_AT_DISMOUNT + 50 m del destino, del lado del vehiculo, en tierra y, si
//--- hay, en la carretera mas cercana (120 m)
VIOC_AT_fnc_dropPos = {
	params ["_v", "_dest"];
	private _d = VIOC_AT_DISMOUNT + 50;
	private _dir = _dest getDir _v;
	private _res = [];
	{
		private _p = _dest getPos [_d, _dir + _x];
		if !(surfaceIsWater _p) exitWith {_res = _p};
	} forEach [0, 25, -25, 50, -50, 80, -80];
	if (count _res < 2) then {_res = getPosATL _v};
	private _roads = (_res nearRoads 120) select {!(surfaceIsWater (getPosATL _x))};
	if (count _roads > 0) then {_res = getPosATL ([_res, _roads] call VIOC_AT_fnc_nearest)};
	[_res select 0, _res select 1, 0]
};

//=====================================================================================================================
// Equipos
//=====================================================================================================================
//--- [grupo, bando] -> true si es un equipo IA que este parche puede manejar
VIOC_AT_fnc_eligible = {
	params ["_g", "_side"];
	if (isNull _g) exitWith {false};
	private _l = leader _g;
	if (isNull _l || {!alive _l} || {isPlayer _l} || {!local _l}) exitWith {false};
	if (((units _g) findIf {isPlayer _x}) >= 0) exitWith {false};
	if !(_g getVariable ["cti_aifsm_handled", false]) exitWith {false};
	if ((_g getVariable ["vioc_air_busy", false]) || {_g getVariable ["vioc_af_scramble", false]} || {_g getVariable ["vioc_specops", false]}) exitWith {false};
	if ((_g getVariable ["cti_nextrespawn", -1]) > time) exitWith {false};
	if ((_g getVariable ["cti_role", ""]) in (missionNamespace getVariable [format ["CTI_SQUADS_%1_KIND_AIR", _side], []])) exitWith {false};
	private _lv = objectParent _l;
	if (!isNull _lv && {(_lv isKindOf "Air") || {_lv isKindOf "Ship"}}) exitWith {false};
	true
};

//--- [grupo, transporte] -> [vivos, a pie, en el transporte, vehiculos propios, pasajeros en propios]
VIOC_AT_fnc_scan = {
	params ["_g", "_tv"];
	private _units = (units _g) select {alive _x && {!(_x getVariable ["vioc_specops", false])}};
	private _foot = [];
	private _inTv = [];
	private _vehs = [];
	{
		private _v = objectParent _x;
		if (isNull _v) then {_foot pushBack _x} else {
			if (_v isEqualTo _tv) then {_inTv pushBack _x} else {_vehs pushBackUnique _v};
		};
	} forEach _units;
	private _own = [];
	private _ownPass = [];
	{
		private _v = _x;
		private _crewIn = false;
		private _pass = [];
		{
			_x params ["_u", "_role", "", "", "_person"];
			if (_u in _units) then {
				if (((toLower _role) == "cargo") || {((toLower _role) == "turret") && {_person}}) then {_pass pushBack _u} else {_crewIn = true};
			};
		} forEach (fullCrew [_v, ""]);
		if (_crewIn && {alive _v} && {_v isKindOf "LandVehicle"} && {!(_v isKindOf "StaticWeapon")}) then {_own pushBack _v; _ownPass append _pass};
	} forEach _vehs;
	[_units, _foot, _inTv, _own, _ownPass]
};

//--- [grupo, bando, tipo de fabrica, variable de compra a distancia] -> fabrica donde el equipo puede comprar (o objNull)
//--- Misma regla que update_ai.fsm: a menos de CTI_BASE_PURCHASE_UNITS_RANGE, o con Control Center al alcance.
VIOC_AT_fnc_factory = {
	params ["_g", "_side", "_ftype", "_remoteVar"];
	private _leader = leader _g;
	private _facs = ([_ftype, (_side) call CTI_CO_FNC_GetSideStructures, _leader] call CTI_CO_FNC_GetSideStructuresByType) select {alive _x};
	if (count _facs == 0) exitWith {objNull};
	private _f = _facs select 0;
	if ((_leader distance _f) <= CTI_BASE_PURCHASE_UNITS_RANGE) exitWith {_f};
	if ((missionNamespace getVariable [_remoteVar, false]) isEqualTo true
		&& {(_f distance _leader) < CTI_BASE_PURCHASE_UNITS_RANGE_CC}
		&& {[_side, CTI_CONTROLCENTER, getPosATL _leader, CTI_BASE_PURCHASE_UNITS_RANGE_CC] call CTI_CO_FNC_HasStructure}) exitWith {_f};
	objNull
};

//--- [bando, clase, precio, tripulacion] -> precio estimado como Server_HandleAIPurchase.sqf (con la tripulacion)
VIOC_AT_fnc_cost = {
	params ["_side", "_model", "_price", "_crew"];
	private _ck = if (_model isKindOf "Tank") then {"Crew"} else {"Soldier"};
	private _cv = missionNamespace getVariable [format ["CTI_%1_%2", _side, _ck], ""];
	if (_cv isEqualType []) then {_cv = _cv param [0, ""]};
	private _c = _price;
	if (_cv isEqualType "" && {_cv != ""}) then {
		private _cd = missionNamespace getVariable [_cv, []];
		if (_cd isEqualType [] && {count _cd > 2} && {(_cd select 2) isEqualType 0}) then {_c = _c + _crew * (_cd select 2)};
	};
	if (CTI_AI_SKILL_BASE < 0.40) then {_c = round (_c / 100)};
	_c
};

//--- [bando, asientos, fondos] -> [variable, clase, tripulacion, precio, tipo de fabrica] o []
VIOC_AT_fnc_pickClass = {
	params ["_side", "_need", "_funds"];
	private _upg = (_side) call CTI_CO_FNC_GetSideUpgrades;
	private _cands = [];
	{
		_x params ["_ftype", "_uIdx"];
		private _lvl = if (_upg isEqualType [] && {count _upg > _uIdx}) then {_upg select _uIdx} else {0};
		{
			private _var = _x;
			private _d = if (_var isEqualType "") then {missionNamespace getVariable [_var, []]} else {[]};
			if (_d isEqualType [] && {count _d > CTI_UNIT_SCRIPTS}) then {
				private _model = _var;
				private _sc = _d select CTI_UNIT_SCRIPTS;
				private _ok = true;
				if (_sc isEqualType []) then {
					if (count _sc > 0 && {(_sc select 0) isEqualType ""}) then {_model = _sc select 0};
					if (count _sc > 1 && {(_sc select 1) isEqualType ""} && {(_sc select 1) != ""}) then {_ok = false};
				} else {
					if (_sc isEqualType "" && {_sc != ""}) then {_ok = false}; //--- apoyo: reparacion, municion, medico, salvamento
				};
				private _ul = _d select CTI_UNIT_UPGRADE;
				if (_ok && {_ul isEqualType 0} && {_ul <= _lvl} && {(_d select CTI_UNIT_PRICE) isEqualType 0}
					&& {isClass (configFile >> "CfgVehicles" >> _model)}
					&& {(_model isKindOf "Car") || {_model isKindOf "Tank"}} && {!(_model isKindOf "StaticWeapon")}
					&& {isNil "VIOC_CA_fnc_banned" || {!([_model] call VIOC_CA_fnc_banned)}}) then {
					private _info = [_model] call VIOC_AT_fnc_classInfo;
					if ((_info select 0) >= _need) then {
						private _cost = [_side, _model, _d select CTI_UNIT_PRICE, _info select 1] call VIOC_AT_fnc_cost;
						if ((_cost * 1.3) <= _funds) then {_cands pushBack [_cost, _var, _model, _info select 1, _ftype, _info select 2]};
					};
				};
			};
		} forEach (missionNamespace getVariable [format ["CTI_%1_%2Units", _side, _ftype], []]);
	} forEach [[CTI_LIGHT, CTI_UPGRADE_LIGHT], [CTI_HEAVY, CTI_UPGRADE_HEAVY]];
	if (count _cands == 0) exitWith {[]};
	_cands sort true;
	private _armed = _cands select {(_x select 5) && {(_x select 0) <= (_funds * 0.3)}};
	private _pool = if (count _armed > 0) then {_armed select [0, 3]} else {_cands select [0, 2]};
	private _p = selectRandom _pool;
	[_p select 1, _p select 2, _p select 3, _p select 0, _p select 4]
};

//--- [vehiculo, grupo de transporte, equipo, bando, comprado, estado inicial]: lo registra como transporte del equipo
VIOC_AT_fnc_register = {
	params ["_v", "_tg", "_g", "_side", "_bought", "_st"];
	_v setVariable ["vioc_at_owner", _g];
	_v setVariable ["vioc_at_prev", _g];
	_v setVariable ["vioc_at_tg", _tg];
	_v setVariable ["vioc_at_side", _side];
	_v setVariable ["vioc_at_bought", _bought];
	_v setVariable ["vioc_at_goto", nil];
	_v setVariable ["VIOC_KEEP", true]; //--- perf_cleanup no lo borra mientras es transporte (se quita al terminar de soltarlo)
	[_v] call VIOC_AT_fnc_prepare;
	if (local _v) then {_v setUnloadInCombat [false, false]}; //--- ni el motor ni LAMBS (canUnloadInCombat) sacan al conductor
	_tg setVariable ["vioc_at_owner", _g];
	_tg setVariable ["lambs_danger_disableGroupAI", true];
	_tg deleteGroupWhenEmpty true;
	_tg addVehicle _v;
	[_tg] call VIOC_AT_fnc_crewPrep;
	_g setVariable ["vioc_at_tv", _v];
	private _i = VIOC_AT_LIST findIf {(_x select 0) isEqualTo _v};
	if (_i < 0) then {VIOC_AT_LIST pushBack [_v, _tg, _g, _bought, _side]} else {VIOC_AT_LIST set [_i, [_v, _tg, _g, _bought, _side]]};
	[_v, _st] call VIOC_AT_fnc_setState;
};

//--- [semilla] -> indice en VIOC_AT_PEND (o -1)
VIOC_AT_fnc_pendFind = {
	params ["_seed"];
	VIOC_AT_PEND findIf {(_x select 0) isEqualTo _seed}
};

//--- Gancho en Server_HandleAIPurchase.sqf (antes de crear el vehiculo): [clase, destino, bando, fabrica, semilla] -> [lugar, dir]
//--- o []. Solo para las compras de este parche (semilla en VIOC_AT_PEND): el punto propio seguro mas cercano al JEFE DEL
//--- EQUIPO (ai_front_spawn no lo ve: el grupo de destino lo acaba de crear la mision y esta vacio).
VIOC_AT_fnc_purchasePos = {
	params ["_model", "_tg", "_side", "_factory", ["_seed", -1]];
	if (isNil "VIOC_FRONT_ReinforcePos" || {_model isKindOf "Man"}) exitWith {[]};
	private _i = [_seed] call VIOC_AT_fnc_pendFind;
	if (_i < 0) exitWith {[]};
	private _g = (VIOC_AT_PEND select _i) select 1;
	if (isNull _g) exitWith {[]};
	[_model, _g, _side, _factory] call VIOC_FRONT_ReinforcePos
};

//--- Gancho en Server_HandleAIPurchase.sqf (vehiculo ya creado con su tripulacion): [vehiculo, grupo de destino, semilla]
VIOC_AT_fnc_onBought = {
	params ["_v", "_tg", ["_seed", -1]];
	if (isNull _v || {!(_tg isEqualType grpNull)} || {isNull _tg}) exitWith {};
	private _i = [_seed] call VIOC_AT_fnc_pendFind;
	if (_i < 0) exitWith {};
	private _p = VIOC_AT_PEND select _i;
	_p set [4, true];
	private _g = _p select 1;
	if (!isNull _g && {(_g getVariable ["vioc_at_pend", -1]) isEqualTo _seed}) then {_g setVariable ["vioc_at_pend", nil]};
	private _ok = !isNull _g && {!isPlayer (leader _g)} && {((units _g) findIf {isPlayer _x}) < 0} && {isNull (_g getVariable ["vioc_at_tv", objNull])};
	if !(_ok) exitWith { //--- el equipo ya no lo necesita: queda suelto (se borra con su tripulacion lejos de jugadores)
		_v setVariable ["VIOC_KEEP", true];
		_v setVariable ["vioc_at_tg", _tg];
		_v setVariable ["vioc_at_bought", true];
		_v setVariable ["vioc_at_state", "FREE"];
		_v setVariable ["vioc_at_t", time];
		VIOC_AT_LIST pushBack [_v, _tg, _g, true, side _tg];
	};
	[_v, _tg, _g, side _tg, true, "GO"] call VIOC_AT_fnc_register;
	[0] call VIOC_AT_fnc_stat;
};

//--- Compras pedidas (bucle): mientras la semilla siga en la cola de la fabrica (cti_queue_processing, que tambien la
//--- conserva mientras Server_HandleAIPurchase la construye) la compra sigue pendiente y el equipo no pide otra. Cuando sale
//--- de la cola sin vehiculo (no hubo fondos, la fabrica cayo, etc.), a los 60 s el equipo queda libre; la entrada se guarda
//--- 10 min mas por si el vehiculo llega tarde. Nunca se cancela ni se borra nada mientras siga en la cola.
VIOC_AT_fnc_pendTick = {
	private _keep = [];
	{
		private _p = _x;
		_p params ["_seed", "_g", "_t0", "_fac", "_done", "_tLeft"];
		private _drop = _done;
		if !(_done) then {
			private _q = if (isNull _fac || {!alive _fac}) then {[]} else {_fac getVariable ["cti_queue_processing", []]};
			if !(_q isEqualType []) then {_q = []};
			if ((_q findIf {(_x isEqualType []) && {count _x > 0} && {(_x select 0) isEqualTo _seed}}) >= 0) then {
				_p set [5, -1];
			} else {
				if (_tLeft < 0) then {_p set [5, time]} else {
					if ((time - _tLeft) > 60 && {!isNull _g} && {(_g getVariable ["vioc_at_pend", -1]) isEqualTo _seed}) then {
						_g setVariable ["vioc_at_pend", nil];
						[format ["%1: la compra de transporte no llego (salio de la cola sin vehiculo)", groupId _g]] call VIOC_AT_fnc_log;
					};
					if ((time - _tLeft) > 600) then {_drop = true};
				};
			};
		};
		if !(_drop) then {_keep pushBack _p};
	} forEach VIOC_AT_PEND;
	VIOC_AT_PEND = _keep;
};

//--- [vehiculo, motivo]: deja de ser transporte del equipo (los pasajeros se bajan; la tripulacion la trata VIOC_AT_fnc_freeTick)
VIOC_AT_fnc_release = {
	params ["_v", "_why"];
	private _g = _v getVariable ["vioc_at_owner", grpNull];
	private _tg = _v getVariable ["vioc_at_tg", grpNull];
	if (!isNull _g && {!isNull _v}) then {
		private _riders = (units _g) select {((objectParent _x) isEqualTo _v) || {(_x getVariable ["vioc_at_ride", objNull]) isEqualTo _v}};
		if (count _riders > 0) then {[_v, _riders] call VIOC_AT_fnc_unload};
		if ((_g getVariable ["vioc_at_tv", objNull]) isEqualTo _v) then {_g setVariable ["vioc_at_tv", nil]};
		_g setVariable ["vioc_at_noMountT", time + 120];
	};
	if (alive _v && {local _v} && {!isNull _tg}) then {[_tg, _v, getPosATL _v, true] call VIOC_AT_fnc_goto};
	private _eh = _v getVariable "vioc_at_eh";
	if (!isNil "_eh") then {_v removeEventHandler ["hit", _eh]; _v setVariable ["vioc_at_eh", nil]};
	_v setVariable ["vioc_at_owner", nil]; //--- el cierre original (vioc_at_lock0) se repone en VIOC_AT_fnc_freeTick, cuando ya bajaron todos
	[_v, "FREE"] call VIOC_AT_fnc_setState;
	[format ["soltado: %1", _why]] call VIOC_AT_fnc_log;
	[6] call VIOC_AT_fnc_stat;
};

//--- Transporte soltado (registro [vehiculo, grupo, equipo, comprado, bando]; el vehiculo puede haber desaparecido): la
//--- tripulacion tomada se baja y vuelve a su equipo; la comprada se borra (con el vehiculo) sin jugadores cerca; si el equipo
//--- anterior ya es tripulacion del vehiculo (lo tomo la FSM), la tripulacion se une al equipo.
VIOC_AT_fnc_freeTick = {
	params ["_rec"];
	_rec params ["_v", "_tg", "_g", "_bought"];
	private _crewTg = if (isNull _tg) then {[]} else {(units _tg) select {alive _x}};
	private _vOk = !isNull _v && {alive _v};
	private _done = false;
	private _gOk = !isNull _g && {!isPlayer (leader _g)} && {((units _g) findIf {isPlayer _x}) < 0};
	if (count _crewTg == 0) then {_done = true} else {
		private _teamCrew = _vOk && {((crew _v) findIf {(_x in (units _g)) && {_x in [driver _v, gunner _v, commander _v]}}) >= 0};
		private _noP = [getPosATL (_crewTg select 0), VIOC_AT_PLAYER_RANGE] call VIOC_AT_fnc_noPlayers;
		if (_teamCrew && {_gOk}) then {
			[_crewTg] call VIOC_AT_fnc_crewRestore;
			_crewTg joinSilent _g;
			_done = true;
		} else {
			if (_bought) then {
				private _others = _vOk && {((crew _v) findIf {alive _x && {!(_x in _crewTg)}}) >= 0};
				if (_noP && {!_others}) then {
					{deleteVehicle _x} forEach _crewTg;
					if (_vOk && {local _v}) then {deleteVehicle _v};
					[7] call VIOC_AT_fnc_stat;
					_done = true;
				};
			} else {
				private _in = _crewTg select {!isNull objectParent _x};
				if (count _in > 0) then {
					{unassignVehicle _x} forEach _in;
					_in orderGetIn false;
					if (_noP) then {{if ((speed (objectParent _x)) < 3) then {moveOut _x}} forEach _in};
				} else {
					[_crewTg] call VIOC_AT_fnc_crewRestore;
					if (_gOk && {((count units _g) + (count _crewTg)) <= (CTI_AI_TEAMS_GROUPSIZE + 2)}) then {
						_crewTg joinSilent _g;
						_done = true;
					} else {
						if (_noP) then {{deleteVehicle _x} forEach _crewTg; _done = true};
					};
				};
			};
		};
	};
	if (_done) then {
		private _i = VIOC_AT_LIST findIf {_x isEqualTo _rec};
		if (_i >= 0) then {VIOC_AT_LIST deleteAt _i};
		if (!isNull _tg && {(count units _tg) == 0}) then {deleteGroup _tg};
		if (!isNull _v) then {
			private _l0 = _v getVariable "vioc_at_lock0";
			if (!isNil "_l0" && {alive _v} && {local _v} && {((crew _v) findIf {alive _x}) < 0}) then {_v lock _l0};
			_v setVariable ["VIOC_KEEP", nil]; //--- desde ahora perf_cleanup lo trata como cualquier vehiculo abandonado
			if !(_bought) then {_v setVariable ["vioc_at_noTake", (_v getVariable ["vioc_at_noTake", -1]) max (time + 300)]};
			{_v setVariable [_x, nil]} forEach ["vioc_at_tg", "vioc_at_prev", "vioc_at_side", "vioc_at_bought", "vioc_at_state", "vioc_at_t", "vioc_at_goto",
				"vioc_at_drop", "vioc_at_dropDest", "vioc_at_idleT", "vioc_at_noDrvT", "vioc_at_farT", "vioc_at_rideT0", "vioc_at_rideMax", "vioc_at_lock0"];
		};
	};
};

//=====================================================================================================================
// B) Equipos con vehiculos propios
//=====================================================================================================================
VIOC_AT_fnc_ownTick = {
	params ["_g", "_side", "_units", "_foot", "_own", "_ownPass", "_dest", "_far", "_threat"];
	private _leader = leader _g;
	[_units] call VIOC_AT_fnc_forceOut;
	//--- los que subieron dejan de estar pendientes; los que se bajaron solos (LAMBS, la FSM) dejan de ser pasajeros nuestros
	{
		private _rv = _x getVariable ["vioc_at_ride", objNull];
		if (!isNull _rv) then {
			if ((objectParent _x) isEqualTo _rv) then {_x setVariable ["vioc_at_rideT", nil]} else {
				if (isNil {_x getVariable "vioc_at_rideT"}) then {_x setVariable ["vioc_at_ride", nil]; _x setVariable ["vioc_at_crew", nil]};
			};
		};
	} forEach _units;
	private _inf = _foot - [_leader];
	private _pend = [_inf, _g] call VIOC_AT_fnc_pending;
	//--- 1) bajar: llegada, combate, impacto, dano o sin destino
	{
		private _v = _x;
		private _riders = (crew _v) select {alive _x && {(_x getVariable ["vioc_at_ride", objNull]) isEqualTo _v} && {!(_x getVariable ["vioc_at_crew", false])}};
		if (count _riders > 0) then {
			private _arr = (count _dest > 1) && {(_v distance2D _dest) < (VIOC_AT_DISMOUNT + 100)};
			private _hit = (time - (_v getVariable ["vioc_at_hitT", -1000])) < 25;
			if (_arr || {_threat} || {_hit} || {!canMove _v} || {(damage _v) > 0.5} || {count _dest < 2}) then {
				private _fight = _threat || {_hit};
				[_v, _riders] call VIOC_AT_fnc_unload;
				[[3, 4] select _fight] call VIOC_AT_fnc_stat;
				_g setVariable ["vioc_at_noMountT", time + 90];
				[format ["%1 %2: %3 bajan de %4 (%5)", _side, groupId _g, count _riders, typeOf _v, ["llegada", "combate"] select _fight]] call VIOC_AT_fnc_log;
			};
		};
	} forEach _own;
	if (_threat) exitWith {};
	//--- 2) subir: torretas vacias siempre (sin combate); asientos de pasajero con el objetivo lejos
	private _cands = _inf select {isNil {_x getVariable "vioc_at_ride"}};
	private _mount = _far && {time > (_g getVariable ["vioc_at_noMountT", -1])};
	if (count _cands > 0) then {
		private _noP = [getPosATL _leader, VIOC_AT_PLAYER_RANGE] call VIOC_AT_fnc_noPlayers;
		{
			private _v = _x;
			if (alive _v && {canMove _v} && {local _v} && {(_v distance2D _leader) < 500} && {(_pend findIf {(_x getVariable ["vioc_at_ride", objNull]) isEqualTo _v}) < 0}) then {
				private _seats = [_v] call VIOC_AT_fnc_freeCrew;
				private _nCrew = count _seats;
				if (_mount) then {_seats append ([_v] call VIOC_AT_fnc_freePass)};
				if (count _seats > 0 && {(_cands findIf {(_x distance2D _v) < VIOC_AT_BOARD_RANGE}) >= 0}) then {
					[_v] call VIOC_AT_fnc_prepare;
					private _np = 0;
					{
						private _e = _x;
						private _near = _cands select {(_x distance2D _v) < VIOC_AT_BOARD_RANGE};
						if (count _near > 0) then {
							private _u = [_v, _near] call VIOC_AT_fnc_nearest;
							[_u, _v, _e, _noP && {(_u distance2D _v) < VIOC_AT_INSTANT}] call VIOC_AT_fnc_seat;
							if (_forEachIndex < _nCrew) then {_u setVariable ["vioc_at_crew", true]} else {_np = _np + 1};
							_cands = _cands - [_u];
						};
					} forEach _seats;
					if (_np > 0) then {
						[2] call VIOC_AT_fnc_stat;
						[format ["%1 %2: %3 suben a %4 (propio)", _side, groupId _g, _np, typeOf _v]] call VIOC_AT_fnc_log;
					};
				};
			};
		} forEach _own;
	};
	//--- 3) infanteria para los asientos libres (modo 1): el equipo casi no tiene y le cabe
	if (VIOC_AT_MODE == 1 && {_g getVariable ["cti_independent", false]} && {time > ((_g getVariable ["vioc_at_infT", -100000]) + VIOC_AT_INF_COOLDOWN)}) then {
		private _free = 0;
		{if (canMove _x) then {_free = _free + count ([_x] call VIOC_AT_fnc_freePass)}} forEach _own;
		if (_free >= 4 && {(count (_inf + _ownPass)) < 2} && {((count units _g) + 3) <= CTI_AI_TEAMS_GROUPSIZE}) then {
			private _sq = missionNamespace getVariable [format ["CTI_SQUAD_%1_Infantry", _side], []];
			private _fac = [_g, _side, CTI_BARRACKS, "CTI_AI_TEAMS_PURCHASE_REMOTE_INFANTRY"] call VIOC_AT_fnc_factory;
			if (!isNull _fac && {_sq isEqualType []} && {count _sq > 2} && {(_sq select 2) isEqualType []} && {count (_sq select 2) > 0}) then {
				_g setVariable ["vioc_at_infT", time];
				[_g, _side, _sq select 2, _fac] call CTI_SE_FNC_AI_PurchaseSquad;
				[5] call VIOC_AT_fnc_stat;
				[format ["%1 %2: compra infanteria para %3 asientos libres", _side, groupId _g, _free]] call VIOC_AT_fnc_log;
			};
		};
	};
};

//=====================================================================================================================
// A) Equipos sin vehiculos propios: transporte con grupo aparte
//=====================================================================================================================
//--- [grupo, bando, a pie] -> vehiculo vacio propio cercano que el equipo puede tomar (o objNull)
VIOC_AT_fnc_findEmpty = {
	params ["_g", "_side", "_foot"];
	private _leader = leader _g;
	private _need = (((count _foot) - 1) min 6) max 3;
	private _hqs = [(missionNamespace getVariable ["CTI_WEST", objNull]) getVariable ["cti_hq", objNull], (missionNamespace getVariable ["CTI_EAST", objNull]) getVariable ["cti_hq", objNull]];
	private _cand = (_leader nearEntities [["Car", "Tank"], VIOC_AT_TAKE_RANGE]) select {
		private _v = _x;
		private _occ = _v getVariable ["cti_occupant", [east, west, resistance, civilian] select (((getNumber (configOf _v >> "side")) max 0) min 3)];
		alive _v && {local _v} && {canMove _v} && {!(_v isKindOf "StaticWeapon")} && {(fuel _v) > 0.15} && {(damage _v) < 0.6}
		&& {(crew _v) findIf {alive _x} < 0}
		&& {(({!alive _x} count (crew _v)) == 0) || {[getPosATL _v, 200] call VIOC_AT_fnc_noPlayers}} //--- muertos dentro: se quitan al tomarlo, sin jugadores cerca
		&& {(_v getVariable ["vioc_at_noTake", -1]) < time}
		&& {isNil {_v getVariable "vioc_at_owner"}} && {isNil {_v getVariable "vioc_at_tg"}}
		&& {_occ isEqualTo _side}
		&& {!(_v getVariable ["vioc_civ", false])} && {!(_v getVariable ["VIOC_KEEP", false])} && {!(_v getVariable ["VIOC_AF_parked", false])}
		&& {!(_v getVariable ["vioc_specops", false])} && {isNil {_v getVariable "cti_gc_noremove"}} && {isNil {_v getVariable "cti_spec"}}
		&& {(_v getVariable ["Owner", ""]) in ["", "0"]}
		&& {(time - (_v getVariable ["VIOC_PERF_pUse", -10000000])) > 1800}
		&& {!(_v in _hqs)}
		&& {isNil "VIOC_PERF_fnc_isSupport" || {!([_v] call VIOC_PERF_fnc_isSupport)}}
		&& {isNil "VIOC_PERF_fnc_inBase" || {!([_v] call VIOC_PERF_fnc_inBase)}}
		&& {!(surfaceIsWater (getPosATL _v))} && {((vectorUp _v) select 2) > 0.7}
		&& {[getPosATL _v, 60] call VIOC_AT_fnc_noPlayers}
		&& {(count ([_v] call VIOC_AT_fnc_freePass)) >= _need}
	};
	[_leader, _cand] call VIOC_AT_fnc_nearest
};

//--- [grupo, bando, vehiculo, a pie]: uno del equipo (dos si el vehiculo va armado y sobran) pasa a ser su tripulacion
VIOC_AT_fnc_takeOver = {
	params ["_g", "_side", "_v", "_foot"];
	private _leader = leader _g;
	private _cands = (_foot - [_leader]) select {isNil {_x getVariable "vioc_at_ride"}};
	if (count _cands < 1) exitWith {false};
	private _tg = createGroup _side;
	if (isNull _tg) exitWith {false};
	{if (!alive _x) then {deleteVehicle _x}} forEach (crew _v); //--- cuerpos en los asientos (findEmpty ya exige que no haya jugadores a 200 m)
	private _noP = [getPosATL _v, VIOC_AT_PLAYER_RANGE] call VIOC_AT_fnc_noPlayers;
	private _drv = [_v, _cands] call VIOC_AT_fnc_nearest;
	_cands = _cands - [_drv];
	[_drv] joinSilent _tg;
	private _crew = [[_drv, [objNull, "driver", -1, [], false]]];
	if ((count _cands) >= 5 && {someAmmo _v}) then {
		private _gs = ([_v] call VIOC_AT_fnc_freeCrew) select {(toLower (_x select 1)) == "gunner"};
		if (count _gs > 0) then {
			private _gun = [_v, _cands] call VIOC_AT_fnc_nearest;
			[_gun] joinSilent _tg;
			_crew pushBack [_gun, _gs select 0];
		};
	};
	[_v, _tg, _g, _side, false, "CREW"] call VIOC_AT_fnc_register;
	{
		_x params ["_u", "_e"];
		[_u, _v, _e, _noP && {(_u distance2D _v) < VIOC_AT_INSTANT}] call VIOC_AT_fnc_seat;
		_u setVariable ["vioc_at_ride", nil];
	} forEach _crew;
	//--- si era de una guarnicion de pueblo, la limpieza del pueblo ya no lo borra
	if (!isNil "CTI_Towns") then {
		{
			private _t = _x;
			{
				private _l = _t getVariable [_x, []];
				if (_l isEqualType [] && {_v in _l}) then {_t setVariable [_x, _l - [_v]]};
			} forEach ["cti_town_occupation_active_vehicles", "cti_town_resistance_active_vehicles"];
		} forEach (CTI_Towns select {(_x distance2D _v) < 1500});
	};
	[1] call VIOC_AT_fnc_stat;
	[format ["%1 %2 toma %3 vacio a %4 m", _side, groupId _g, typeOf _v, round (_v distance2D _leader)]] call VIOC_AT_fnc_log;
	true
};

//--- [grupo, bando, a pie] -> true si se pidio la compra de un transporte
VIOC_AT_fnc_buy = {
	params ["_g", "_side", "_foot"];
	if (VIOC_AT_MODE != 1 || {!(_g getVariable ["cti_independent", false])}) exitWith {false};
	//--- solo equipos de rol infanteria: los ligeros/pesados que perdieron sus vehiculos los vuelven a comprar por la FSM
	if !((_g getVariable ["cti_role", ""]) in (missionNamespace getVariable [format ["CTI_SQUADS_%1_KIND_INFANTRY", _side], []])) exitWith {false};
	if (time < ((_g getVariable ["vioc_at_buyT", -100000]) + VIOC_AT_BUY_COOLDOWN)) exitWith {false};
	private _leader = leader _g;
	private _funds = [_g, _side] call CTI_CO_FNC_GetFunds;
	if !(_funds isEqualType 0) exitWith {false};
	private _n = (count _foot) min 10;
	private _pick = [];
	{
		if (count _pick == 0) then {_pick = [_side, _x, _funds] call VIOC_AT_fnc_pickClass};
	} forEach [_n, ((_n - 2) max VIOC_AT_MIN_INF) min _n];
	if (count _pick == 0) exitWith {_g setVariable ["vioc_at_buyT", time - VIOC_AT_BUY_COOLDOWN + 120]; false};
	_pick params ["_var", "_model", "_crewN", "_cost", "_ftype"];
	if (!isNil "VIOC_PERF_fnc_overBudget" && {[_crewN] call VIOC_PERF_fnc_overBudget}) exitWith {_g setVariable ["vioc_at_buyT", time - VIOC_AT_BUY_COOLDOWN + 120]; false};
	private _fac = [_g, _side, _ftype, ["CTI_AI_TEAMS_PURCHASE_REMOTE_LIGHT", "CTI_AI_TEAMS_PURCHASE_REMOTE_HEAVY"] select (_ftype == CTI_HEAVY)] call VIOC_AT_fnc_factory;
	if (isNull _fac) exitWith {_g setVariable ["vioc_at_buyT", time - VIOC_AT_BUY_COOLDOWN + 120]; false};
	//--- tiene que nacer cerca del equipo: punto adelantado (ai_front_spawn) o la fabrica, sin mar en medio
	private _lpos = getPosATL _leader;
	private _spawn = if (isNil "VIOC_FRONT_ReinforcePos") then {[]} else {[_model, _g, _side, _fac] call VIOC_FRONT_ReinforcePos};
	private _sp = if (count _spawn > 1) then {_spawn select 0} else {getPosATL _fac};
	private _far = (_sp distance2D _lpos) > VIOC_AT_MAX_DELIVERY;
	private _wet = (count _spawn < 2) && {!isNil "VIOC_FRONT_DryPath"} && {!([_sp, _lpos] call VIOC_FRONT_DryPath)};
	if (_far || {_wet}) exitWith {_g setVariable ["vioc_at_buyT", time - VIOC_AT_BUY_COOLDOWN + 180]; false};
	//--- destino = el BANDO: Server_HandleAIPurchase crea el grupo de la tripulacion despues de cobrar (no queda ningun grupo
	//--- vacio esperando en la cola); la compra se reconoce por su semilla
	private _seed = time + random 10000 - random 500 + diag_frameNo;
	while {([_seed] call VIOC_AT_fnc_pendFind) >= 0} do {_seed = _seed + 0.37};
	VIOC_AT_PEND pushBack [_seed, _g, time, _fac, false, -1];
	_g setVariable ["vioc_at_pend", _seed];
	_g setVariable ["vioc_at_buyT", time];
	[_side, _g, _side, _var, _fac, [true, true, true, true, "", true], _seed, 1] call CTI_SE_FNC_OnClientPurchase;
	[format ["%1 %2 compra %3 (%4 asientos, %5 de tripulacion, %6 de %7) en %8", _side, groupId _g, _model, ([_model] call VIOC_AT_fnc_classInfo) select 0, _crewN, _cost, round _funds, _fac getVariable ["cti_structure_type", ""]]] call VIOC_AT_fnc_log;
	true
};

//--- [vehiculo, equipo, a pie]: el conductor murio; uno del equipo lo reemplaza (o se suelta el transporte)
VIOC_AT_fnc_recrew = {
	params ["_v", "_g", "_foot"];
	private _tg = _v getVariable ["vioc_at_tg", grpNull];
	private _drv = driver _v;
	if (!isNull _drv && {alive _drv} && {!(_drv in (units _tg))}) exitWith {[_v, "otro grupo maneja el vehiculo"] call VIOC_AT_fnc_release};
	if (isNil {_v getVariable "vioc_at_noDrvT"}) then {_v setVariable ["vioc_at_noDrvT", time]};
	private _cands = (_foot - [leader _g]) select {(_x distance2D _v) < 300 && {isNil {_x getVariable "vioc_at_ride"}}};
	if (!isNull _tg && {count _cands > 2} && {!([leader _g, VIOC_AT_THREAT] call VIOC_AT_fnc_threat)} && {[getPosATL _v, 200] call VIOC_AT_fnc_noPlayers}) exitWith {
		if (!isNull _drv && {!alive _drv}) then {deleteVehicle _drv};
		private _u = [_v, _cands] call VIOC_AT_fnc_nearest;
		[_u] joinSilent _tg;
		[_u, _v, [objNull, "driver", -1, [], false], ([getPosATL _v, VIOC_AT_PLAYER_RANGE] call VIOC_AT_fnc_noPlayers) && {(_u distance2D _v) < VIOC_AT_INSTANT}] call VIOC_AT_fnc_seat;
		_u setVariable ["vioc_at_ride", nil];
		_v setVariable ["vioc_at_noDrvT", nil];
		[_v, "CREW"] call VIOC_AT_fnc_setState;
	};
	if ((time - (_v getVariable ["vioc_at_noDrvT", time])) > 90) then {[_v, "sin conductor"] call VIOC_AT_fnc_release};
};

//--- [vehiculo, equipo, a pie, en el transporte, destino, lejos, combate]: maquina de estados del transporte
VIOC_AT_fnc_tvTick = {
	params ["_v", "_g", "_foot", "_inTv", "_dest", "_far", "_threat"];
	private _tg = _v getVariable ["vioc_at_tg", grpNull];
	private _st = _v getVariable ["vioc_at_state", "GO"];
	if (!alive _v || {isNull _tg} || {!canMove _v}) exitWith {[_v, "vehiculo perdido, inmovil o sin tripulacion"] call VIOC_AT_fnc_release};
	if (!local _v) exitWith {};
	[_foot + _inTv] call VIOC_AT_fnc_forceOut;
	//--- equipo sin infanteria: se suelta a los 10 min
	if ((count _foot) + (count _inTv) < 2) then {
		if (isNil {_v getVariable "vioc_at_idleT"}) then {_v setVariable ["vioc_at_idleT", time]};
	} else {_v setVariable ["vioc_at_idleT", nil]};
	if ((time - (_v getVariable ["vioc_at_idleT", time])) > VIOC_AT_IDLE_RELEASE) exitWith {[_v, "el equipo se quedo sin infanteria"] call VIOC_AT_fnc_release};
	//--- jefe demasiado lejos (por ejemplo reaparecio en la base): se suelta a los VIOC_AT_FAR_RELEASE s
	if (((_v distance2D (leader _g)) > VIOC_AT_MAX_CHASE) && {!((objectParent (leader _g)) isEqualTo _v)}) then {
		if (isNil {_v getVariable "vioc_at_farT"}) then {_v setVariable ["vioc_at_farT", time]};
	} else {_v setVariable ["vioc_at_farT", nil]};
	if ((time - (_v getVariable ["vioc_at_farT", time])) > VIOC_AT_FAR_RELEASE) exitWith {[_v, "el jefe esta demasiado lejos"] call VIOC_AT_fnc_release};
	[_tg] call VIOC_AT_fnc_crewPrep;
	if (_st == "CREW") exitWith {[_v, _g, _foot, _tg] call VIOC_AT_fnc_stCrew};
	private _drv = driver _v;
	if (isNull _drv || {!alive _drv} || {!(_drv in (units _tg))}) exitWith {[_v, _g, _foot] call VIOC_AT_fnc_recrew};
	{
		_x setVariable ["cti_ai_lastpos", nil]; //--- el control de atascados de update_ai.fsm no mueve el transporte
		if ((_x getVariable ["vioc_at_ride", objNull]) isEqualTo _v) then {_x setVariable ["vioc_at_rideT", nil]};
	} forEach _inTv;
	//--- fuera de LOAD/RIDE/DROP, los que se bajaron por su cuenta dejan de ser pasajeros
	if !(_st in ["LOAD", "RIDE", "DROP"]) then {
		{
			if (((_x getVariable ["vioc_at_ride", objNull]) isEqualTo _v) && {isNil {_x getVariable "vioc_at_rideT"}}) then {_x setVariable ["vioc_at_ride", nil]};
		} forEach _foot;
	};
	private _vThreat = [_drv, VIOC_AT_THREAT] call VIOC_AT_fnc_threat;
	private _hit = (time - (_v getVariable ["vioc_at_hitT", -1000])) < 25;
	switch (_st) do {
		case "GO": {[_v, _g, _foot, _inTv, _dest, _far, _threat, _vThreat, _tg] call VIOC_AT_fnc_stGo};
		case "LOAD": {[_v, _g, _foot, _inTv, _dest, _threat, _vThreat, _hit, _tg] call VIOC_AT_fnc_stLoad};
		case "RIDE": {[_v, _g, _foot, _inTv, _dest, _threat, _vThreat, _hit, _tg] call VIOC_AT_fnc_stRide};
		case "DROP": {[_v, _g, _inTv, _tg] call VIOC_AT_fnc_stDrop};
		default {[_v, _g, _foot, _inTv, _far, _threat, _vThreat, _tg] call VIOC_AT_fnc_stSupport};
	};
};

//--- CREW: la tripulacion tomada del equipo sube (al instante sin jugadores cerca, a los VIOC_AT_LOAD_TIME s como mucho)
VIOC_AT_fnc_stCrew = {
	params ["_v", "_g", "_foot", "_tg"];
	private _crewTg = (units _tg) select {alive _x};
	if (count _crewTg == 0) exitWith {[_v, "sin tripulacion"] call VIOC_AT_fnc_release};
	private _out = _crewTg select {isNull objectParent _x};
	if (count _out == 0 && {alive driver _v}) exitWith {[_v, "GO"] call VIOC_AT_fnc_setState};
	if ((time - (_v getVariable ["vioc_at_t", time])) > VIOC_AT_LOAD_TIME) then {
		if ([getPosATL _v, VIOC_AT_PLAYER_RANGE] call VIOC_AT_fnc_noPlayers) then {
			{
				if ((_x distance2D _v) < 300) then {
					if (isNull driver _v) then {_x assignAsDriver _v; _x moveInDriver _v} else {
						private _gs = ([_v] call VIOC_AT_fnc_freeCrew);
						if (count _gs > 0) then {[_x, _v, _gs select 0, true] call VIOC_AT_fnc_seat; _x setVariable ["vioc_at_ride", nil]};
					};
				};
			} forEach _out;
		};
		if !(alive driver _v) then {
			_v setVariable ["vioc_at_noTake", time + 900]; //--- que no lo vuelvan a intentar enseguida
			[_v, "la tripulacion no subio"] call VIOC_AT_fnc_release;
		} else {[_v, "GO"] call VIOC_AT_fnc_setState};
	};
};

//--- GO: va a buscar al jefe del equipo
VIOC_AT_fnc_stGo = {
	params ["_v", "_g", "_foot", "_inTv", "_dest", "_far", "_threat", "_vThreat", "_tg"];
	private _leader = leader _g;
	if (count _inTv > 0) exitWith {[_v, "RIDE"] call VIOC_AT_fnc_setState};
	if (_threat || {_vThreat} || {!_far} || {(count _foot) < 2} || {!isNull objectParent _leader} || {(_v distance2D _leader) > VIOC_AT_MAX_CHASE}) exitWith {
		[_tg, _v, getPosATL _v, true] call VIOC_AT_fnc_goto;
		[_v, "SUPPORT"] call VIOC_AT_fnc_setState;
	};
	if ((_v distance2D _leader) <= VIOC_AT_PICKUP) exitWith {
		[_tg, _v, getPosATL _v, true] call VIOC_AT_fnc_goto;
		private _n = [_v, _g, _foot, _tg] call VIOC_AT_fnc_board;
		if (_n > 0) then {[_v, "LOAD"] call VIOC_AT_fnc_setState} else {
			_g setVariable ["vioc_at_noMountT", time + 120];
			[_v, "SUPPORT"] call VIOC_AT_fnc_setState;
		};
	};
	if (([_v] call VIOC_AT_fnc_stuck) >= 9) exitWith {
		_g setVariable ["vioc_at_noMountT", time + 180];
		[_v, "SUPPORT"] call VIOC_AT_fnc_setState;
	};
	private _p = getPosATL _leader;
	if ((_v getVariable ["vioc_at_stuck", 0]) in [4, 7]) then {_p = _leader getPos [30 + random 40, random 360]};
	[_tg, _v, _p, (_v getVariable ["vioc_at_stuck", 0]) in [4, 7]] call VIOC_AT_fnc_goto;
};

//--- [vehiculo, equipo, a pie, grupo del transporte] -> cuantos suben. Torretas vacias del transporte con gente del equipo si
//--- sobra (pasan al grupo del transporte), luego pasajeros: el jefe primero y despues los mas cercanos.
VIOC_AT_fnc_board = {
	params ["_v", "_g", "_foot", "_tg"];
	private _leader = leader _g;
	private _cands = _foot select {(_x distance2D _v) < VIOC_AT_BOARD_RANGE};
	if !(_leader in _cands) exitWith {0};
	[_v] call VIOC_AT_fnc_prepare;
	private _noP = [getPosATL _v, VIOC_AT_PLAYER_RANGE] call VIOC_AT_fnc_noPlayers;
	{
		if ((count _cands) >= 6) then {
			private _u = [_v, _cands - [_leader]] call VIOC_AT_fnc_nearest;
			if (!isNull _u) then {
				_cands = _cands - [_u];
				[_u] joinSilent _tg;
				[_u, _v, _x, _noP && {(_u distance2D _v) < VIOC_AT_INSTANT}] call VIOC_AT_fnc_seat;
				_u setVariable ["vioc_at_ride", nil];
			};
		};
	} forEach ([_v] call VIOC_AT_fnc_freeCrew);
	private _keys = [];
	private _rest = _cands - [_leader];
	{_keys pushBack [_x distance2D _v, _forEachIndex]} forEach _rest;
	_keys sort true;
	private _order = [_leader] + (_keys apply {_rest select (_x select 1)});
	private _seats = [_v] call VIOC_AT_fnc_freePass;
	private _n = 0;
	{
		if (_n >= count _seats) exitWith {};
		[_x, _v, _seats select _n, _noP && {(_x distance2D _v) < VIOC_AT_INSTANT}] call VIOC_AT_fnc_seat;
		_n = _n + 1;
	} forEach _order;
	_n
};

//--- LOAD: espera a que suban; el jefe tiene que ir dentro
VIOC_AT_fnc_stLoad = {
	params ["_v", "_g", "_foot", "_inTv", "_dest", "_threat", "_vThreat", "_hit", "_tg"];
	private _leader = leader _g;
	private _pend = _foot select {(_x getVariable ["vioc_at_ride", objNull]) isEqualTo _v};
	if (_threat || {_vThreat} || {_hit} || {count _dest < 2}) exitWith {
		[_v, _inTv + _pend] call VIOC_AT_fnc_unload;
		_g setVariable ["vioc_at_noMountT", time + 120];
		[_v, "SUPPORT"] call VIOC_AT_fnc_setState;
	};
	if ((count _pend) > 0 && {(time - (_v getVariable ["vioc_at_t", time])) > VIOC_AT_LOAD_TIME}) then {
		if ([getPosATL _v, VIOC_AT_PLAYER_RANGE] call VIOC_AT_fnc_noPlayers) then {
			private _seats = [_v] call VIOC_AT_fnc_freePass;
			private _i = 0;
			{
				if (_i < count _seats && {(_x distance2D _v) < 300}) then {[_x, _v, _seats select _i, true] call VIOC_AT_fnc_seat; _i = _i + 1};
			} forEach _pend;
		};
		private _still = _pend select {isNull objectParent _x};
		if (count _still > 0) then {[_v, _still] call VIOC_AT_fnc_unload};
		_pend = [];
	};
	if (count _pend == 0) then {
		if ((objectParent _leader) isEqualTo _v) then {
			private _drop = [_v, _dest] call VIOC_AT_fnc_dropPos;
			_v setVariable ["vioc_at_drop", _drop];
			_v setVariable ["vioc_at_dropDest", +_dest];
			_v setVariable ["vioc_at_rideT0", time];
			_v setVariable ["vioc_at_rideMax", 60 + (_v distance2D _drop) / 5]; //--- tiempo maximo del viaje (5 m/s de media)
			[_tg, _v, _drop, true] call VIOC_AT_fnc_goto;
			[2] call VIOC_AT_fnc_stat;
			[format ["%1 %2: %3 suben a %4, objetivo a %5 m", side _g, groupId _g, count ((units _g) select {(objectParent _x) isEqualTo _v}), typeOf _v, round (_v distance2D _dest)]] call VIOC_AT_fnc_log;
			[_v, "RIDE"] call VIOC_AT_fnc_setState;
		} else {
			private _riders = (units _g) select {(objectParent _x) isEqualTo _v};
			if (count _riders > 0) then {[_v, _riders] call VIOC_AT_fnc_unload};
			_g setVariable ["vioc_at_noMountT", time + 180];
			[_v, "SUPPORT"] call VIOC_AT_fnc_setState;
		};
	};
};

//--- RIDE: lleva al equipo hasta el punto de bajada
VIOC_AT_fnc_stRide = {
	params ["_v", "_g", "_foot", "_inTv", "_dest", "_threat", "_vThreat", "_hit", "_tg"];
	if (count _inTv == 0) exitWith {[_v, "SUPPORT"] call VIOC_AT_fnc_setState};
	private _leader = leader _g;
	private _lThreat = ((objectParent _leader) isEqualTo _v) && {[_leader, VIOC_AT_THREAT] call VIOC_AT_fnc_threat};
	private _outside = _foot findIf {(_x getVariable ["vioc_at_ride", objNull]) isEqualTo _v} >= 0; //--- alguien se bajo (LAMBS, la FSM)
	private _unas = _inTv findIf {!((assignedVehicle _x) isEqualTo _v)} >= 0;                        //--- la FSM les quito el vehiculo
	if (_hit || {_vThreat} || {_lThreat} || {(damage _v) > 0.5}) exitWith {[_v, _g, _inTv, _tg, 4] call VIOC_AT_fnc_toDrop};
	if (count _dest < 2 || {(_v distance2D _dest) < (VIOC_AT_DISMOUNT + 150)} || {_outside} || {_unas}) exitWith {[_v, _g, _inTv, _tg, 3] call VIOC_AT_fnc_toDrop};
	private _dd = _v getVariable ["vioc_at_dropDest", []];
	private _drop = _v getVariable ["vioc_at_drop", []];
	if (count _drop < 2 || {count _dd < 2} || {(_dd distance2D _dest) > 200}) then {
		_drop = [_v, _dest] call VIOC_AT_fnc_dropPos;
		_v setVariable ["vioc_at_drop", _drop];
		_v setVariable ["vioc_at_dropDest", +_dest];
		_v setVariable ["vioc_at_rideT0", time];
		_v setVariable ["vioc_at_rideMax", 60 + (_v distance2D _drop) / 5];
		[_tg, _v, _drop, true] call VIOC_AT_fnc_goto;
	};
	if ((_v distance2D _drop) < 80) exitWith {[_v, _g, _inTv, _tg, 3] call VIOC_AT_fnc_toDrop};
	if (isNil {_v getVariable "vioc_at_rideT0"}) then {_v setVariable ["vioc_at_rideT0", time]; _v setVariable ["vioc_at_rideMax", 60 + (_v distance2D _drop) / 5]};
	if ((time - (_v getVariable "vioc_at_rideT0")) > (_v getVariable ["vioc_at_rideMax", 600])) exitWith { //--- da vueltas sin llegar
		[format ["%1 %2: viaje demasiado largo, bajan donde estan", side _g, groupId _g]] call VIOC_AT_fnc_log;
		[_v, _g, _inTv, _tg, 3] call VIOC_AT_fnc_toDrop;
	};
	private _s = [_v] call VIOC_AT_fnc_stuck;
	if (_s >= 9) exitWith {[_v, _g, _inTv, _tg, 3] call VIOC_AT_fnc_toDrop};
	if (_s in [4, 7]) then {[_tg, _v, _drop getPos [20 + random 30, random 360], true] call VIOC_AT_fnc_goto};
};

//--- [vehiculo, equipo, en el transporte, grupo del transporte, tipo (3 llegada, 4 combate)]: pasa a DROP y para ya
VIOC_AT_fnc_toDrop = {
	params ["_v", "_g", "_inTv", "_tg", "_kind"];
	_v setVariable ["vioc_at_dropK", _kind];
	_v setVariable ["vioc_at_rideT0", nil];
	_v setVariable ["vioc_at_stopT", nil];
	_v setVariable ["vioc_at_unloadT", nil];
	[_v, "DROP"] call VIOC_AT_fnc_setState;
	[_v, _g, _inTv, _tg] call VIOC_AT_fnc_stDrop;
};

//--- DROP: para, se bajan y el equipo recarga su orden (sigue a pie)
VIOC_AT_fnc_stDrop = {
	params ["_v", "_g", "_inTv", "_tg"];
	private _t0 = _v getVariable ["vioc_at_t", time];
	if (isNil {_v getVariable "vioc_at_stopT"}) then {
		[_tg, _v, getPosATL _v, true] call VIOC_AT_fnc_goto;
		_v setVariable ["vioc_at_stopT", time];
	};
	private _riders = (units _g) select {((objectParent _x) isEqualTo _v) || {(_x getVariable ["vioc_at_ride", objNull]) isEqualTo _v}};
	if (isNil {_v getVariable "vioc_at_unloadT"} && {((speed _v) < 5) || {(time - _t0) > 8}}) then {
		[_v, _riders] call VIOC_AT_fnc_unload;
		_v setVariable ["vioc_at_unloadT", time];
		_g setVariable ["cti_team_reload", true];
		[_v getVariable ["vioc_at_dropK", 3]] call VIOC_AT_fnc_stat;
		[format ["%1 %2: %3 bajan de %4 (%5)", side _g, groupId _g, count _riders, typeOf _v, ["llegada", "combate"] select ((_v getVariable ["vioc_at_dropK", 3]) == 4)]] call VIOC_AT_fnc_log;
	};
	if (!isNil {_v getVariable "vioc_at_unloadT"} && {(count _inTv == 0) || {(time - (_v getVariable "vioc_at_unloadT")) > 60}}) then {
		_v setVariable ["vioc_at_unloadT", nil];
		_v setVariable ["vioc_at_stopT", nil];
		_v setVariable ["vioc_at_dropT", time];
		_g setVariable ["vioc_at_noMountT", time + 90];
		[_v, "SUPPORT"] call VIOC_AT_fnc_setState;
	};
};

//--- SUPPORT: armado, sigue a la infanteria a 150-250 m; sin armas, se queda atras y se aparta de enemigos cercanos.
//--- Con una orden lejana y sin combate vuelve a buscarlos (GO).
VIOC_AT_fnc_stSupport = {
	params ["_v", "_g", "_foot", "_inTv", "_far", "_threat", "_vThreat", "_tg"];
	private _leader = leader _g;
	if (count _inTv > 0 && {((_inTv findIf {(_x getVariable ["vioc_at_ride", objNull]) isEqualTo _v}) >= 0)}) exitWith {[_v, "RIDE"] call VIOC_AT_fnc_setState};
	private _dl = _v distance2D _leader;
	if (_far && {!_threat} && {!_vThreat} && {(count _foot) >= 2} && {isNull objectParent _leader} && {_dl < VIOC_AT_MAX_CHASE}
		&& {time > (_g getVariable ["vioc_at_noMountT", -1])} && {(time - (_v getVariable ["vioc_at_dropT", -1000])) > 90}) exitWith {
		[_v, "GO"] call VIOC_AT_fnc_setState;
	};
	if (_dl > VIOC_AT_MAX_CHASE) exitWith {}; //--- espera; VIOC_AT_fnc_tvTick lo suelta si sigue asi VIOC_AT_FAR_RELEASE s
	private _drv = driver _v;
	if ((someAmmo _v) && {alive (gunner _v)}) then {
		if (_dl > 260) then {[_tg, _v, _leader getPos [160, _leader getDir _v]] call VIOC_AT_fnc_goto};
	} else {
		private _e = _drv findNearestEnemy _drv;
		if (!isNull _e && {(_e distance _v) < 300}) then {
			[_tg, _v, _v getPos [250, _e getDir _v]] call VIOC_AT_fnc_goto;
		} else {
			if (_dl > 450) then {[_tg, _v, _leader getPos [300, _leader getDir _v]] call VIOC_AT_fnc_goto};
		};
	};
};

//--- [grupo, bando, a pie, en el transporte, destino, lejos, combate, transporte]
VIOC_AT_fnc_transportTeam = {
	params ["_g", "_side", "_foot", "_inTv", "_dest", "_far", "_threat", "_tv"];
	if (!isNull _tv) exitWith {[_tv, _g, _foot, _inTv, _dest, _far, _threat] call VIOC_AT_fnc_tvTick};
	[_foot] call VIOC_AT_fnc_forceOut;
	if (!isNil {_g getVariable "vioc_at_pend"}) exitWith {}; //--- compra en la cola de la fabrica (la sigue VIOC_AT_fnc_pendTick)
	if (!_far || {_threat} || {(count _foot) < VIOC_AT_MIN_INF} || {time < (_g getVariable ["vioc_at_noMountT", -1])}) exitWith {};
	if (({private _rv = _x select 0; !isNull _rv && {alive _rv} && {!((_rv getVariable ["vioc_at_state", "FREE"]) isEqualTo "FREE")} && {(_x select 4) isEqualTo _side}} count VIOC_AT_LIST)
		+ ({!(_x select 4) && {((_x select 1) getVariable ["vioc_at_pend", -1]) isEqualTo (_x select 0)} && {(side (_x select 1)) isEqualTo _side}} count VIOC_AT_PEND) >= VIOC_AT_MAX_SIDE) exitWith {};
	private _done = false;
	if (time > ((_g getVariable ["vioc_at_takeT", -1000]) + 60)) then {
		_g setVariable ["vioc_at_takeT", time];
		private _v = [_g, _side, _foot] call VIOC_AT_fnc_findEmpty;
		if (!isNull _v) then {_done = [_g, _side, _v, _foot] call VIOC_AT_fnc_takeOver};
	};
	if (!_done) then {[_g, _side, _foot] call VIOC_AT_fnc_buy};
};

//--- [grupo, bando]: una pasada para un equipo
VIOC_AT_fnc_teamTick = {
	params ["_g", "_side"];
	private _tv = _g getVariable ["vioc_at_tv", objNull];
	if (!isNull _tv && {!((_tv getVariable ["vioc_at_owner", grpNull]) isEqualTo _g)}) then {_g setVariable ["vioc_at_tv", nil]; _tv = objNull};
	([_g, _tv] call VIOC_AT_fnc_scan) params ["_units", "_foot", "_inTv", "_own", "_ownPass"];
	private _leader = leader _g;
	private _dest = [_g] call VIOC_AT_fnc_dest;
	private _far = (count _dest > 1) && {(_leader distance2D _dest) > VIOC_AT_MOUNT_EFF};
	private _threat = [_leader, VIOC_AT_THREAT] call VIOC_AT_fnc_threat;
	if (count _own > 0) then {
		if (!isNull _tv) then {[_tv, "el equipo ya tiene vehiculos propios"] call VIOC_AT_fnc_release};
		[_g, _side, _units, _foot, _own, _ownPass, _dest, _far, _threat] call VIOC_AT_fnc_ownTick;
	} else {
		[_g, _side, _foot, _inTv, _dest, _far, _threat, _tv] call VIOC_AT_fnc_transportTeam;
	};
};

//=====================================================================================================================
// Consola
//=====================================================================================================================
VIOC_AT_fnc_teams = {
	private _r = [];
	{
		private _side = _x;
		{if (!isNull _x && {!isPlayer leader _x}) then {_r pushBack _x}} forEach ((_side) call CTI_CO_FNC_GetSideGroups);
	} forEach [west, east];
	_r
};

VIOC_AT_fnc_nearTeam = {
	private _c = if (hasInterface && {!isNull player}) then {player} else {[0, 0, 0]};
	private _best = grpNull;
	private _bd = 1e9;
	{
		if (alive leader _x && {((units _x) findIf {isPlayer _x}) < 0}) then {
			private _d = (leader _x) distance2D _c;
			if (_d < _bd) then {_best = _x; _bd = _d};
		};
	} forEach (call VIOC_AT_fnc_teams);
	_best
};

VIOC_AT_fnc_testOrder = {
	params [["_g", grpNull, [grpNull]], ["_pos", [], [[]]]];
	if (isNull _g || {count _pos < 2}) exitWith {"falta el grupo o la posicion"};
	_g setVariable ["cti_order", CTI_ORDER_MOVE, true];
	_g setVariable ["cti_order_pos", [_pos select 0, _pos select 1, 0], true];
	format ["%1 (%2): orden MOVE a %3 m", groupId _g, side _g, round ((leader _g) distance2D _pos)]
};

VIOC_AT_fnc_info = {
	private _lines = [format (["VIOC_AT modo %1, subir > %2 m, bajar a %3 m | compras %4, tomados %5, subidas %6, bajadas llegada %7 / combate %8, compras de infanteria %9, soltados %10, borrados %11 | transportes %12, compras en cola %13",
		VIOC_AT_MODE, VIOC_AT_MOUNT_EFF, VIOC_AT_DISMOUNT] + VIOC_AT_INFO + [count VIOC_AT_LIST, {!(_x select 4)} count VIOC_AT_PEND])];
	{
		private _g = _x;
		private _tv = _g getVariable ["vioc_at_tv", objNull];
		([_g, _tv] call VIOC_AT_fnc_scan) params ["_units", "_foot", "_inTv", "_own", "_ownPass"];
		private _dest = [_g] call VIOC_AT_fnc_dest;
		_lines pushBack format ["%1 %2 [%3]: %4 vivos, a pie %5, en transporte %6, vehiculos propios %7 (pasajeros %8), objetivo %9 m, transporte %10 %11",
			side _g, groupId _g, _g getVariable ["cti_role", "?"], count _units, count _foot, count _inTv, count _own, count _ownPass,
			if (count _dest > 1) then {round ((leader _g) distance2D _dest)} else {-1},
			if (isNull _tv) then {"-"} else {typeOf _tv}, if (isNull _tv) then {""} else {_tv getVariable ["vioc_at_state", ""]}];
	} forEach (call VIOC_AT_fnc_teams);
	private _txt = _lines joinString "\n";
	copyToClipboard _txt;
	_txt
};

//=====================================================================================================================
// Bucle del servidor
//=====================================================================================================================
VIOC_AT_fnc_loop = {
	waitUntil {sleep 2; !isNil "CTI_Init_Server"};
	sleep 30;
	VIOC_AT_MODE = missionNamespace getVariable ["VIOC_AI_TRANSPORT", 1];
	if !(VIOC_AT_MODE isEqualType 0) then {VIOC_AT_MODE = 1};
	if (VIOC_AT_MODE <= 0) exitWith {diag_log "[VIOC_AT] apagado (VIOC_AI_TRANSPORT = 0)"};
	VIOC_AT_MOUNT = missionNamespace getVariable ["VIOC_AI_TRANSPORT_MOUNT", 900];
	VIOC_AT_DISMOUNT = missionNamespace getVariable ["VIOC_AI_TRANSPORT_DISMOUNT", 500];
	if !(VIOC_AT_MOUNT isEqualType 0) then {VIOC_AT_MOUNT = 900};
	if !(VIOC_AT_DISMOUNT isEqualType 0) then {VIOC_AT_DISMOUNT = 500};
	VIOC_AT_MOUNT_EFF = VIOC_AT_MOUNT max (VIOC_AT_DISMOUNT + 400);
	CTI_AI_TEAMS_CARGO_VEHICLES_DISEMBARK_RANGE = VIOC_AT_DISMOUNT; //--- update_ai.fsm baja a los pasajeros a esta distancia (antes 850)
	diag_log format ["[VIOC_AT] activo: modo %1, subir > %2 m, bajar a %3 m", VIOC_AT_MODE, VIOC_AT_MOUNT_EFF, VIOC_AT_DISMOUNT];
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		{
			private _side = _x;
			private _cmd = (_side) call CTI_CO_FNC_GetSideCommander;
			if (isNil "_cmd") then {_cmd = grpNull};
			{
				if (!(_x isEqualTo _cmd) && {[_x, _side] call VIOC_AT_fnc_eligible}) then {[_x, _side] call VIOC_AT_fnc_teamTick};
			} forEach ((_side) call CTI_CO_FNC_GetSideGroups);
		} forEach [west, east];
		call VIOC_AT_fnc_pendTick;
		//--- transportes soltados, destruidos o desaparecidos (su tripulacion se sigue por el registro) y los de equipos que
		//--- ya no son de la IA
		{
			private _rec = _x;
			private _v = _rec select 0;
			if (isNull _v) then {[_rec] call VIOC_AT_fnc_freeTick} else {
				if (!alive _v && {!((_v getVariable ["vioc_at_state", "FREE"]) isEqualTo "FREE")}) then {[_v, "vehiculo destruido"] call VIOC_AT_fnc_release};
				if ((_v getVariable ["vioc_at_state", "FREE"]) isEqualTo "FREE") then {[_rec] call VIOC_AT_fnc_freeTick} else {
					private _g = _rec select 2;
					if (isNull _g || {isPlayer (leader _g)} || {((units _g) findIf {isPlayer _x}) >= 0}) then {[_v, "el equipo ya no es de la IA"] call VIOC_AT_fnc_release};
				};
			};
		} forEach (+VIOC_AT_LIST);
		sleep VIOC_AT_PERIOD;
	};
};

[] spawn VIOC_AT_fnc_loop;

